package io.github.some_example_name;
import io.github.some_example_name.database.*;import io.github.some_example_name.model.*;import java.util.*;
public final class DraftClass2005RegressionTest{public static void main(String[]a){require(DraftClassRepository.hasHistoricalClass(2005),"not registered");List<Player>ps=DraftClassRepository.getClassForYear(2005);require(ps.size()==60,"Expected 60");Set<String>old=new HashSet<>();for(int y=1970;y<=2004;y++)for(Player p:DraftClassRepository.getClassForYear(y))old.add(n(p.getName()));Map<String,Player>m=new HashMap<>();for(Player p:ps){require(p.getAge()==18,"age "+p.getName());require(!old.contains(n(p.getName())),"Repeated "+p.getName());require(m.put(p.getName(),p)==null,"Duplicate "+p.getName());}expect(m,"Lionel Messi",Position.RW,82,82,28,84,96,99);expect(m,"Blaise Matuidi",Position.CM,54,68,72,93,67,91);expect(m,"Jô",Position.ST,69,55,29,92,66,79);System.out.println("Draft class 2005: 60 unique prospects with pre-balanced potential OK.");}private static String n(String s){return s.toLowerCase(Locale.ROOT);}private static void expect(Map<String,Player>m,String n,Position q,int at,int pa,int de,int f,int dr,int pot){Player x=m.get(n);require(x!=null&&x.getPrimaryPosition()==q&&x.getPotential()==pot&&x.getTechnicalAttributes().getAtaque()==at&&x.getTechnicalAttributes().getPasse()==pa&&x.getTechnicalAttributes().getDefesa()==de&&x.getTechnicalAttributes().getFisico()==f&&x.getTechnicalAttributes().getDrible()==dr,"Bad "+n);}private static void require(boolean b,String s){if(!b)throw new AssertionError(s);}}
